"""The base of the typed configs (mallard.config, generated by tools/dev/input_config.py)."""
import numbers
import sys


def quantity(value):
    """A dimensional value as the input writes it: a number (SI, or the key's documented unit), a string with its
    unit ("5 mm"), or (value, unit)."""
    if isinstance(value, tuple) and len(value) == 2 and isinstance(value[1], str):
        number = value[0]
        if isinstance(number, bool) or not isinstance(number, numbers.Real):
            raise TypeError(f"a quantity is (number, unit), not {value!r}")
        text = str(int(number)) if isinstance(number, numbers.Integral) else repr(float(number))
        return f"{text} {value[1]}"
    if isinstance(value, list):
        return [quantity(v) for v in value]
    return value


class Inline:
    """A dict written as one inline table, as given ({type = "box", size = [...]}), where a typed table's keyword
    takes it: for keys the catalog does not list for that table (a region's parameters of another type)."""

    def __init__(self, table):
        self.table = dict(table)

    def __repr__(self):
        return f"Inline({self.table!r})"


class Table:
    """The keys of one table of the input, with their values, in the order given: mallard.Case.set writes them."""

    _keys = {}

    def __init__(self, path, values):
        self._path = path
        self._entries = []
        module = sys.modules[type(self).__module__]
        for name, value in values.items():
            if value is None:
                continue
            key, kind, child = self._keys[name]
            if isinstance(value, Inline):
                self._entries.append((key, value.table))
            elif kind == "quantity":
                self._entries.append((key, quantity(value)))
            elif kind == "map":
                for k, v in dict(value).items():
                    self._entries.append((f"{key}.{k}", v))
            elif kind == "array":
                cls = getattr(module, child)
                for i, item in enumerate(value):
                    self._nest(f"{key}[{i}]", item if isinstance(item, Table) else cls(**item))
            elif kind == "table" and isinstance(value, (Table, dict)):
                cls = getattr(module, child)
                self._nest(key, value if isinstance(value, Table) else cls(**value))
            else:
                self._entries.append((key, value))

    def _nest(self, key, table):
        self._entries += [(f"{key}.{k}", v) for k, v in table.entries()]

    @property
    def path(self):
        """The table's key path in the input ("numerics.face_reconstruction", "probes[0]"); "" for a table only its
        parent's keyword takes."""
        return self._path

    def entries(self):
        """[(key, value)]: the keys set, relative to path, in order."""
        return list(self._entries)

    def __repr__(self):
        args = ", ".join(f"{k}={v!r}" for k, v in self._entries)
        return f"{type(self).__name__}({args})"
